window.products.push({"id":868093,"name":"Genuine 30726 VacMaster 3-Mil 10 Inch by 15 Inch Chamber Vacuum Packaging Pouches","category":"homeandappliances","retail price":96.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/31f7t6B9W+L._AC_.jpg","description":"VacMaster 3-Mil Chamber Pouches provide optimum freshness and a positive reliable seal. The Nylon/Polyethylene pouch extends the shelf life of food products and can protect non-food items from air, water and other contaminants. These puncture resistant pouches shield food from freezer burn and dehydration, keeping food fresh up to five times longer. VacMaster pouches are transparent, allowing for easy identification of the product. The pouches work in conjunction with any chamber machine, but are intended for use with all VacMaster VP Series Chamber Machines. Pouches are not for use with suction type vacuum sealers.","images":["https://m.media-amazon.com/images/I/31f7t6B9W+L._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Vacmaster","source_asin":"B00WRH5644","category_path":"Home & Kitchen"},"sku":"BM-868093","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00WRH5644","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00WRH5644","price_pending":true,"merchant_ready":false});
